        jl("SkyyRqPa", SUI.icon_cell(RID, item=item, w=C3_W, h=ROW_H, icon=ROW_IC, icon_left=ROW_IL, state=state, anchor={"bottom": ROW_GAP})),
        jl(RID, SUI.label(RID + "Nm", "", "strong", w=NAME_W, h=20, col=J_("rc", SUI.RARITY["Normal"]), anchor={"left": TXT_L, "top": 2}, fit=False)),
