HELPERS = r'''# 0.2.2: one tab -> its own search + sort (0 Armor, 1 Items, 2 Inventory, 3 bag blocks, 4 Weapons); never touches the page / selection
M(page, r"""
public void go(int nv) {
  if (nv == this.view) return;
  if (this.view >= 0 && this.view < 5) { this.qs[this.view] = this.q; this.sorts[this.view] = this.sort; }
  this.view = nv;
  if (nv >= 0 && nv < 5) { this.q = this.qs[nv] == null ? "" : this.qs[nv]; this.sort = this.sorts[nv]; }
}""")
# 0.2.2 WEAPONS: SkyyGear's weapon family (Weapon_* ids: swords ... wands, spellbooks, shields, ammo) + an asset with a Weapon part and no Tool
# part (a mod weapon with its own prefix); tools (lifelong ones too) and fishing rods are Items
M(page, r"""
public static boolean weapon(String id) {
  if (id == null || id.length() == 0) return false;
  if (id.startsWith("Weapon_")) return true;
  if (id.startsWith("Tool_") || id.startsWith("SkyyFishing_Rod_")) return false;
  @ITEM@ it = @PKG@.WdCodec.itemOf(id);
  if (it == null) return false;
  try { return it.getWeapon() != null && it.getTool() == null; } catch (Throwable t) { return false; }
}""")
M(page, "public static int tabOf(@PKG@.WdEntry e) { return e.space == 0 ? 0 : (weapon(e.itemId()) ? 4 : 1); }")
M(page, r"""
public static int weapons(@PKG@.WdData d) {
  int n = 0;
  java.util.Iterator it = d.entries.values().iterator();
  while (it.hasNext()) { @PKG@.WdEntry e = (@PKG@.WdEntry) it.next(); if (e.space == 1 && weapon(e.itemId())) n++; }
  return n;
}""")
# a hotbar slot click: the tab of what it picks; Keep / Empty / Pocket = the Weapons or Items tab you are on, else Weapons
M(page, r"""
public int hotTab(@PKG@.WdEntry e) {
  if (e != null && e.space == 1) return tabOf(e);
  return this.view == 1 || this.view == 4 ? this.view : 4;
}""")
# gear:fn:rollsLine "Rare - Lv 20 - Strength +12 - Crit Chance +5%" -> "Strength +12 - Crit Chance +5%" ("" when none / unidentified)
M(page, r"""
public static String modsOf(String rl) {
  if (rl == null || rl.length() == 0 || rl.startsWith("Unidentified")) return "";
  StringBuilder sb = new StringBuilder();
  int i = 0;
  int n = 0;
  while (i <= rl.length()) {
    int j = rl.indexOf(" - ", i);
    if (j < 0) j = rl.length();
    String part = rl.substring(i, j);
    if (n > 0 && !part.startsWith("Lv ") && part.length() > 0) { if (sb.length() > 0) sb.append(" - "); sb.append(part); }
    n++;
    i = j + 3;
  }
  return sb.toString();
}""")
# SkyyGear's own text for a gear item IN Requip: { name (reforge + real name) or null, modifiers or "" }; null = none. READ ONLY: the bridge
# gets a clone of the stored stack's metadata. Cached per page by the stack object (an ItemStack never changes; a new stack = asked again).
M(page, r"""
public String[] gearText(@PKG@.WdEntry e) {
  if (e == null || !e.in || e.kind || e.stack == null) return null;
  Object c = this.gtx.get(e.eid);
  if (c instanceof Object[] && ((Object[]) c)[0] == e.stack) return (String[]) ((Object[]) c)[1];
  String[] out = null;
  try {
    if (@PKG@.WdCodec.gearDoc(e.stack) != null) {
      String id = e.stack.getItemId();
      org.bson.BsonDocument md = e.stack.getMetadata();
      String nm = null;
      String ms = "";
      java.util.function.Function f = @PKG@.WdLog.fn("gear:fn:describe");
      Object o = f == null ? null : f.apply(new Object[] { id, md.clone() });
      if (o instanceof String[] && ((String[]) o).length > 0 && ((String[]) o)[0] != null && ((String[]) o)[0].trim().length() > 0) nm = ((String[]) o)[0].trim();
      f = @PKG@.WdLog.fn("gear:fn:rollsLine");
      o = f == null ? null : f.apply(new Object[] { id, md.clone() });
      if (o instanceof String) ms = modsOf((String) o);
      if (nm != null || ms.length() > 0) out = new String[] { nm, ms };
    }
  } catch (Throwable t) {
    @PKG@.WdLog.warnOnce("rowtext", "SkyyGear's item text could not be read for the Requip list (the row shows Requip's own record): " + t);
    out = null;
  }
  if (this.gtx.size() > 4000) this.gtx.clear();
  this.gtx.put(e.eid, new Object[] { e.stack, out });
  return out;
}""")
M(page, r"""
public String twinKey(@PKG@.WdEntry e) {
  String[] g = gearText(e);
  return g == null ? "" : (g[0] == null ? "" : g[0]) + "|" + g[1];
}""")
# two rows that would read the same (same item, rarity, level and SkyyGear text) -> #1, #2 in the default list order (newest first, ties
# by eid = WdSort mode 0: the default list reads #1 above #2; over the whole profile, so the number never changes with the sort, the search
# or the page - it moves only when a twin joins or leaves the pool); 0 = no twin
M(page, r"""
public int twinNo(@PKG@.WdData d, @PKG@.WdEntry e) {
  if (e.kind) return 0;
  String me = null;
  int same = 0;
  int rank = 1;
  java.util.Iterator it = d.entries.values().iterator();
  while (it.hasNext()) {
    @PKG@.WdEntry x = (@PKG@.WdEntry) it.next();
    if (x == e || x.kind || x.space != e.space || x.lv != e.lv || !x.rar.equals(e.rar) || !x.itemId().equals(e.itemId())) continue;
    if (me == null) me = twinKey(e);
    if (!twinKey(x).equals(me)) continue;
    same++;
    if (x.addedAt > e.addedAt || (x.addedAt == e.addedAt && x.eid.compareTo(e.eid) < 0)) rank++;
  }
  return same == 0 ? 0 : rank;
}""")
# the name a row, the detail panel and the Take out / Forget prompts show: SkyyGear's (or the readable id) + "  #N" for a twin, cut with
# "..." to the row's name label (the #N always stays)
M(page, r"""
public String nameOf(@PKG@.WdData d, @PKG@.WdEntry e) {
  String[] g = gearText(e);
  String nm = g != null && g[0] != null ? g[0] : @PKG@.WdCodec.pretty(e.itemId());
  int tw = twinNo(d, e);
  String suf = tw > 0 ? "  #" + tw : "";
  return fit(nm, NAME_MAX - textW(suf, true), true) + suf;
}""")
# one row's text: { name, the grey line, the tag } - name = nameOf; tag = "Lv N" / "x64"; grey line = rarity - state (only when not simply
# in Requip) - picked in N loadouts - modifiers, cut with "..." to its label (the modifiers go first)
M(page, r"""
public String[] rowText(@PKG@.WdData d, @PKG@.WdEntry e, @IC@[] cs) {
  String[] g = gearText(e);
  String nm = nameOf(d, e);
  String tag = e.kind ? "x" + qtyText(e.count) : (e.lv >= 0 ? "Lv " + e.lv : "");
  StringBuilder sb = new StringBuilder();
  if (!e.kind && e.rar.length() > 0) sb.append(@PKG@.WdCodec.rarWord(e.rar));
  String st = "";
  if (e.gone != null && e.gone.length() > 0) st = "used up";
  else if (!e.in && !e.kind) st = @PKG@.WdInv.findStamp(cs, e.eid) != null ? "on you" : "NOT WITH YOU";
  if (st.length() > 0) { if (sb.length() > 0) sb.append(" - "); sb.append(st); }
  int pk = d.picked(e.eid);
  if (pk > 0) { if (sb.length() > 0) sb.append(" - "); sb.append("picked in ").append(pk).append(pk == 1 ? " loadout" : " loadouts"); }
  if (g != null && g[1].length() > 0) { if (sb.length() > 0) sb.append(" - "); sb.append(g[1]); }
  if (sb.length() == 0) sb.append(e.kind ? e.count + " in Requip" : "In Requip");
  return new String[] { nm, fit(sb.toString(), SUB_MAX, false), tag };
}""")
# the search also finds the SkyyGear name a row shows (a reforge name: "sharp")
M(page, r"""
public boolean nameHit(@PKG@.WdEntry e, String qq) {
  String[] g = gearText(e);
  return g != null && g[0] != null && g[0].toLowerCase().indexOf(qq) >= 0;
}""")
'''
