M(cfgc, r"""
public static synchronized String migFree(java.nio.file.Path f) {
  MIG_LAST = "";
  if (f == null) return "";
  try {
    if (!java.nio.file.Files.exists(f, new java.nio.file.LinkOption[0])) return "";
    byte[] old = java.nio.file.Files.readAllBytes(f);
    Object[] r = migPlan(new String(old, "ISO-8859-1"));
    if (r == null) return "";
    byte[] data = ((String) r[0]).getBytes("ISO-8859-1");
    boolean mig = ((Boolean) r[2]).booleanValue();
    boolean add = ((Boolean) r[4]).booleanValue();
    if (!migSame(old, data, mig, add)) {
      @PKG@.WdLog.warn("config.properties NOT updated for 0.2.2 (10 free loadouts): the update would change another setting (the file is used as it is; the next start tries again)");
      return "";
    }
    int fi = migFileIdx();
    if (fi < 0) return "";
    @PKG@.CfgHist.snapshot(fi, old, @PKG@.CfgHist.stamp(), MIG_WHO, "before the 0.2.2 free loadouts update (4 -> 10)");
    if (!migSaved(fi, old)) {
      @PKG@.WdLog.warn("config.properties NOT updated for 0.2.2 (10 free loadouts): the old file could not be kept in config-history (the next start tries again)");
      return "";
    }
    @PKG@.CfgRows.atomicWrite(f, data);
    String[] rows = (String[]) r[1];
    for (int i = 0; i + 2 < rows.length; i += 3) @PKG@.CfgLog.enqueue(migLine(rows[i], rows[i + 1], rows[i + 2]));
    if (rows.length > 0) @PKG@.CfgLog.flush();
    String msg = "config.properties updated for 0.2.2: " + (mig ? MIG_KEY + " 4 -> 10" + (add ? " (line added - the file had none and used 4)" : "") + " (every profile has 10 free loadouts; Server Setup -> Changes -> Undo = 4)" : "no setting changed - 0.2.2 marker added") + " - the old file is in config-history";
    @PKG@.WdLog.info(msg);
    String kept = (String) r[3];
    if (kept.length() > 0) { @PKG@.WdLog.info(kept); msg = msg + "\n" + kept; }
    MIG_LAST = msg;
    return msg;
  } catch (Throwable t) {
    @PKG@.WdLog.warn("could not update config.properties for 0.2.2 (10 free loadouts; the file is used as it is): " + t);
    return "";
  }
}""")
